class Solution {
public:
    int houseOfCards(int n) {
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for (int k = 1; 3 * k - 1 <= n; k++) {
            int cost = 3 * k - 1;
            for (int i = n; i >= cost; i--) {
                dp[i] += dp[i - cost];
            }
        }
        return dp[n];
    }
};

